(()=>{
const $=id=>document.getElementById(id);let built=false;
function layout(){if(built||!document.body.classList.contains('standalone-workspace'))return;built=true;
 const form=$('editor'),library=document.querySelector('.library');
 library.prepend($('new'));$('new').classList.add('wide');const searchLabel=document.querySelector('label[for="search"]');$('new').after(searchLabel,$('search'));
 const permanent=$('permanent-id').closest('label'),more=document.createElement('details');more.className='more-details';more.innerHTML='<summary>More details</summary>';more.append(permanent);form.querySelector('.editor-heading').after(Object.assign(document.createElement('h3'),{textContent:'1. Details',className:'section-title'}));
 const firstGrid=$('qid').closest('.form-grid');firstGrid.after(more);
 const publication=document.createElement('section');publication.className='publication-section';publication.innerHTML='<h3 class="section-title">4. Publication</h3>';
 publication.append($('status').closest('label'));publication.append($('discussion-enabled').closest('label'));
 const statusHint=firstGrid.nextElementSibling?.nextElementSibling;if(statusHint?.classList.contains('hint'))publication.append(statusHint);
 const categoryGrid=$('subject').closest('.form-grid');firstGrid.append($('subject').closest('label'),$('topic').closest('label'));categoryGrid.remove();firstGrid.classList.add('compact-details');more.after($('category-hint'));
 $('text').closest('label').before(Object.assign(document.createElement('h3'),{textContent:'2. Question & choices',className:'section-title'}));
 $('explanation').closest('label').before(Object.assign(document.createElement('h3'),{textContent:'3. Explanation',className:'section-title'}));
 const notes=$('notes').closest('label'),notesDetails=document.createElement('details');notesDetails.innerHTML='<summary>Answer notes (reference only)</summary>';notes.before(notesDetails);notesDetails.append(notes);
 const saveBar=form.querySelector('.save-bar');saveBar.before(publication);saveBar.classList.add('sticky-save');
 const buttons=document.createElement('div');buttons.className='save-actions';const preview=document.createElement('button');preview.type='button';preview.className='secondary';preview.textContent='Preview as learner';const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Cancel changes';cancel.onclick=()=>window.QuestionEditor.cancel();$('save').textContent='Save changes';buttons.append(preview,cancel,$('save'));saveBar.append(buttons);
 const state=document.createElement('span');state.className='sticky-state';state.textContent=$('save-state').textContent;saveBar.prepend(state);new MutationObserver(()=>state.textContent=$('save-state').textContent).observe($('save-state'),{childList:true,characterData:true,subtree:true});
 const dialog=document.createElement('dialog');dialog.id='learner-preview';dialog.innerHTML='<div class="preview-heading"><h2>Learner preview</h2><button type="button" class="secondary">Close</button></div><p class="hint">Preview of your unsaved wording and formatting. This does not save changes or create an attempt.</p><article id="preview-question"></article><details id="preview-feedback"><summary>Explanation after submission</summary><div></div></details>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();
 preview.onclick=()=>{const q=window.QuestionEditor.preview(),box=$('preview-question');box.replaceChildren();const heading=document.createElement('p');heading.className='eyebrow';heading.textContent=q.display_code;const text=document.createElement('div');text.className='formatted-text';text.innerHTML=window.presentQuestion(q.text);box.append(heading,text);if(q.image){const img=document.createElement('img');img.src=q.image;img.alt='Question image';img.style.cssText='max-width:100%;max-height:300px;object-fit:contain';box.append(img)}if(q.type==='range'){const input=document.createElement('input');input.placeholder='Your numerical answer';input.setAttribute('aria-label','Preview numerical answer');box.append(input)}else for(const c of q.choices){const label=document.createElement('label');label.className='option';const input=document.createElement('input');input.type=q.type==='single'?'radio':'checkbox';input.name='preview-choice';label.append(input,document.createTextNode(c.id+'. '+c.text));box.append(label)}$('preview-feedback').open=false;$('preview-feedback').querySelector('div').innerHTML=RichText.render(q.explanation||'No explanation entered.')+RichText.explanationImage(q);dialog.showModal()};
}
window.addEventListener('question-workflow',layout);layout();
})();
